// receipt-report.js — reduce a run log (JSONL of events) into a receipt report.
//
// Usage: node receipt-report.js LOGFILE
//
// Node.js builtins only. Importing this module does not run the CLI.

import { readFileSync, realpathSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

function fail(message) {
  throw new Error(message);
}

// Validate one parsed JSON value as an event. Returns exactly the five
// required fields (extra fields are ignored, including for duplicate
// comparison). Types are never coerced.
function validateEvent(event, lineNo) {
  if (event === null || typeof event !== 'object' || Array.isArray(event)) {
    fail(`line ${lineNo}: event must be a JSON object`);
  }
  const { id, job, attempt, seq, type } = event;
  if (typeof id !== 'string' || id.length === 0) {
    fail(`line ${lineNo}: "id" must be a nonempty string`);
  }
  if (typeof job !== 'string' || job.length === 0) {
    fail(`line ${lineNo}: "job" must be a nonempty string`);
  }
  if (typeof attempt !== 'number' || !Number.isSafeInteger(attempt) || attempt < 1) {
    fail(`line ${lineNo}: "attempt" must be a positive safe integer`);
  }
  if (typeof seq !== 'number' || !Number.isSafeInteger(seq) || seq < 0) {
    fail(`line ${lineNo}: "seq" must be a nonnegative safe integer`);
  }
  if (type !== 'started' && type !== 'succeeded' && type !== 'failed') {
    fail(`line ${lineNo}: "type" must be exactly "started", "succeeded", or "failed"`);
  }
  return { id, job, attempt, seq, type };
}

function sameRequiredFields(a, b) {
  return a.job === b.job && a.attempt === b.attempt && a.seq === b.seq && a.type === b.type;
}

export function reduceEvents(text) {
  if (typeof text !== 'string') {
    fail('input must be a UTF-8 JSONL string');
  }

  // CRLF (and bare CR) line endings and a missing final newline are allowed;
  // whitespace-only lines are ignored.
  const lines = text.split(/\r\n|\n|\r/);
  const uniqueEvents = new Map(); // id -> first event with that id
  let duplicates = 0;

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const line = lines[i].trim();
    if (line === '') continue;

    let parsed;
    try {
      parsed = JSON.parse(line);
    } catch {
      fail(`line ${lineNo}: invalid JSON`);
    }
    const event = validateEvent(parsed, lineNo);

    // Deduplicate by id before reducing.
    const first = uniqueEvents.get(event.id);
    if (first === undefined) {
      uniqueEvents.set(event.id, event);
    } else if (sameRequiredFields(first, event)) {
      duplicates += 1;
    } else {
      fail(`line ${lineNo}: duplicate id with different required fields: ${JSON.stringify(event.id)}`);
    }
  }

  // Group surviving events by (job, attempt).
  const byJob = new Map(); // job -> Map(attempt -> { start, terminal })
  for (const event of uniqueEvents.values()) {
    let attempts = byJob.get(event.job);
    if (attempts === undefined) {
      attempts = new Map();
      byJob.set(event.job, attempts);
    }
    let record = attempts.get(event.attempt);
    if (record === undefined) {
      record = { start: null, terminal: null };
      attempts.set(event.attempt, record);
    }
    if (event.type === 'started') {
      // A second start for this (job, attempt) necessarily has a different id,
      // because identical ids were deduplicated above.
      if (record.start !== null) {
        fail(`job ${JSON.stringify(event.job)} attempt ${event.attempt}: repeated start with different id`);
      }
      record.start = event;
    } else {
      // A second terminal is either a repeated terminal (different id, since
      // identical ids were deduplicated) or a contradiction (both succeeded
      // and failed present). Both are errors.
      if (record.terminal !== null) {
        fail(`job ${JSON.stringify(event.job)} attempt ${event.attempt}: repeated or contradictory terminal event`);
      }
      record.terminal = event;
    }
  }

  const jobs = [];
  for (const [job, attempts] of byJob) {
    const attemptReports = [];
    for (const [attempt, record] of attempts) {
      if (record.start === null) {
        fail(`job ${JSON.stringify(job)} attempt ${attempt}: terminal event without a start event`);
      }
      const { start, terminal } = record;
      if (terminal !== null && terminal.seq <= start.seq) {
        fail(`job ${JSON.stringify(job)} attempt ${attempt}: terminal seq ${terminal.seq} must be strictly greater than start seq ${start.seq}`);
      }
      attemptReports.push({
        attempt,
        status: terminal === null ? 'running' : terminal.type,
        startedSeq: start.seq,
        finishedSeq: terminal === null ? null : terminal.seq,
      });
    }
    attemptReports.sort((a, b) => a.attempt - b.attempt);
    jobs.push({ job, attempts: attemptReports });
  }

  // Jobs in JavaScript string "<"/">" order (UTF-16 code units, not locale).
  jobs.sort((a, b) => (a.job < b.job ? -1 : a.job > b.job ? 1 : 0));
  return { jobs, duplicates };
}

function runCli(argv) {
  if (argv.length !== 1) {
    process.stderr.write('usage: node receipt-report.js LOGFILE\n');
    return 2;
  }
  const file = argv[0];
  let text;
  try {
    text = readFileSync(file, 'utf8');
  } catch (err) {
    process.stderr.write(`receipt-report: unable to read ${JSON.stringify(file)}: ${err.message}\n`);
    return 2;
  }
  let report;
  try {
    report = reduceEvents(text);
  } catch (err) {
    process.stderr.write(`receipt-report: ${err.message}\n`);
    return 2;
  }
  process.stdout.write(`${JSON.stringify(report)}\n`);
  return 0;
}

const isMainModule = (() => {
  try {
    return (
      Boolean(process.argv[1]) &&
      import.meta.url === pathToFileURL(realpathSync(resolve(process.argv[1]))).href
    );
  } catch {
    return false;
  }
})();

if (isMainModule) {
  const code = runCli(process.argv.slice(2));
  if (code !== 0) process.exitCode = code;
}

export default reduceEvents;

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { reduceEvents } from '../receipt-report.js';

const jsonl = events => events.map(event => JSON.stringify(event)).join('\n');
const script = fileURLToPath(new URL('../receipt-report.js', import.meta.url));
const runCli = (...args) => spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });

test('empty and whitespace-only input', () => {
  assert.deepEqual(reduceEvents(''), { jobs: [], duplicates: 0 });
  assert.deepEqual(reduceEvents(' \t\r\n  \n'), { jobs: [], duplicates: 0 });
});

test('CRLF endings and missing final newline are allowed', () => {
  const events = [
    { id: 't', job: 'j', attempt: 1, seq: 2, type: 'succeeded' },
    { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
  ];
  const crlf = events.map(event => JSON.stringify(event)).join('\r\n'); // no final newline
  assert.deepEqual(reduceEvents(crlf), {
    jobs: [{ job: 'j', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 1, finishedSeq: 2 }] }],
    duplicates: 0,
  });
});

test('blank lines in the middle are ignored', () => {
  const text = [
    '',
    '   ',
    JSON.stringify({ id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' }),
    '\r',
    JSON.stringify({ id: 't', job: 'j', attempt: 1, seq: 2, type: 'failed' }),
    '',
  ].join('\n');
  assert.deepEqual(reduceEvents(text), {
    jobs: [{ job: 'j', attempts: [{ attempt: 1, status: 'failed', startedSeq: 1, finishedSeq: 2 }] }],
    duplicates: 0,
  });
});

test('duplicates: every extra identical copy is counted, other fields ignored', () => {
  const e = { id: 'a', job: 'j', attempt: 1, seq: 3, type: 'started' };
  const report = reduceEvents(jsonl([e, { ...e, extra: 1 }, { ...e, note: 'x', other: [1, 2] }, e]));
  assert.equal(report.duplicates, 3);
  assert.deepEqual(report.jobs, [{ job: 'j', attempts: [{ attempt: 1, status: 'running', startedSeq: 3, finishedSeq: null }] }]);
});

test('a repeated id with any different required field is an error', () => {
  const e = { id: 'a', job: 'j', attempt: 1, seq: 3, type: 'started' };
  for (const delta of [{ seq: 4 }, { type: 'succeeded' }, { job: 'k' }, { attempt: 2 }]) {
    assert.throws(() => reduceEvents(jsonl([e, { ...e, ...delta }])), JSON.stringify(delta));
  }
});

test('orphan terminal is an error', () => {
  assert.throws(() => reduceEvents(jsonl([{ id: 't', job: 'j', attempt: 1, seq: 2, type: 'succeeded' }])));
});

test('repeated start with different ids is an error', () => {
  assert.throws(() => reduceEvents(jsonl([
    { id: 's1', job: 'j', attempt: 1, seq: 1, type: 'started' },
    { id: 's2', job: 'j', attempt: 1, seq: 1, type: 'started' },
  ])));
});

test('repeated or contradictory terminals are errors', () => {
  assert.throws(() => reduceEvents(jsonl([
    { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
    { id: 't1', job: 'j', attempt: 1, seq: 2, type: 'succeeded' },
    { id: 't2', job: 'j', attempt: 1, seq: 3, type: 'succeeded' },
  ])));
  assert.throws(() => reduceEvents(jsonl([
    { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
    { id: 't1', job: 'j', attempt: 1, seq: 2, type: 'succeeded' },
    { id: 't2', job: 'j', attempt: 1, seq: 3, type: 'failed' },
  ])));
});

test('terminal seq must be strictly greater than start seq', () => {
  const start = { id: 's', job: 'j', attempt: 1, seq: 5, type: 'started' };
  assert.throws(() => reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 5, type: 'succeeded' }])));
  assert.throws(() => reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 4, type: 'failed' }])));
  // strictly greater passes
  assert.equal(reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 6, type: 'succeeded' }])).jobs[0].attempts[0].status, 'succeeded');
});

test('attempt gaps are allowed and attempts are independent', () => {
  const report = reduceEvents(jsonl([
    { id: 's1', job: 'j', attempt: 1, seq: 1, type: 'started' },
    { id: 's5', job: 'j', attempt: 5, seq: 1, type: 'started' },
    { id: 't5', job: 'j', attempt: 5, seq: 2, type: 'failed' },
    { id: 's9', job: 'j', attempt: 9, seq: 2, type: 'started' },
  ]));
  assert.deepEqual(report.jobs, [{ job: 'j', attempts: [
    { attempt: 1, status: 'running', startedSeq: 1, finishedSeq: null },
    { attempt: 5, status: 'failed', startedSeq: 1, finishedSeq: 2 },
    { attempt: 9, status: 'running', startedSeq: 2, finishedSeq: null },
  ]}]);
});

test('seqs may be shared across attempts and jobs', () => {
  const report = reduceEvents(jsonl([
    { id: 's1', job: 'j', attempt: 1, seq: 5, type: 'started' },
    { id: 't1', job: 'j', attempt: 1, seq: 9, type: 'failed' },
    { id: 's2', job: 'j', attempt: 2, seq: 5, type: 'started' },
    { id: 'sk', job: 'k', attempt: 1, seq: 4, type: 'started' },
    { id: 'tk', job: 'k', attempt: 1, seq: 5, type: 'succeeded' },
  ]));
  assert.deepEqual(report, {
    jobs: [
      { job: 'j', attempts: [
        { attempt: 1, status: 'failed', startedSeq: 5, finishedSeq: 9 },
        { attempt: 2, status: 'running', startedSeq: 5, finishedSeq: null },
      ]},
      { job: 'k', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 4, finishedSeq: 5 }]},
    ],
    duplicates: 0,
  });
});

test('field validation is strict and never coerces', () => {
  const ok = { id: 'a', job: 'j', attempt: 1, seq: 0, type: 'started' };
  const bad = [
    { ...ok, attempt: 0 },
    { ...ok, attempt: -1 },
    { ...ok, attempt: 1.5 },
    { ...ok, attempt: '1' },
    { ...ok, attempt: 2 ** 53 },
    { ...ok, attempt: true },
    { ...ok, seq: -1 },
    { ...ok, seq: 0.5 },
    { ...ok, seq: '0' },
    { ...ok, seq: 2 ** 53 },
    { ...ok, id: '' },
    { ...ok, id: 1 },
    { ...ok, job: '' },
    { ...ok, job: null },
    { ...ok, type: 'Started' },
    { ...ok, type: 'done' },
    { ...ok, type: 5 },
  ];
  for (const event of bad) {
    assert.throws(() => reduceEvents(jsonl([event])), JSON.stringify(event));
  }
  assert.throws(() => reduceEvents(jsonl([{ job: 'j', attempt: 1, seq: 0, type: 'started' }])), 'missing id');
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'j', seq: 0, type: 'started' }])), 'missing attempt');
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'j', attempt: 1, type: 'started' }])), 'missing seq');
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'j', attempt: 1, seq: 0 }])), 'missing type');
  // safe-integer boundary is valid
  assert.equal(reduceEvents(jsonl([{ ...ok, seq: 2 ** 53 - 1 }])).duplicates, 0);
});

test('non-object or invalid JSON lines are rejected', () => {
  for (const line of ['null', '[1]', '42', '"x"', 'true', '{bad', '']) {
    if (line === '') continue; // covered by the empty test
    assert.throws(() => reduceEvents(line), line);
  }
});

test('ids such as __proto__ and whitespace/unicode strings are ordinary', () => {
  const report = reduceEvents(jsonl([
    { id: '__proto__', job: 'j', attempt: 1, seq: 1, type: 'started' },
    { id: '  spaced id  ', job: 'job with spaces', attempt: 1, seq: 2, type: 'succeeded' },
    { id: 'unicodé', job: '日本 job', attempt: 1, seq: 0, type: 'started' },
  ]));
  assert.deepEqual(report.jobs.map(job => job.job), ['j', 'job with spaces', '日本 job']);
  assert.equal(report.jobs[0].attempts[0].status, 'running');
  assert.equal(report.jobs[1].attempts[0].status, 'succeeded');
  // __proto__ did not escape into the result object
  assert.equal(report.__proto__, undefined);
});

test('jobs sort by UTF-16 code units, attempts numerically', () => {
  const report = reduceEvents(jsonl([
    { id: 'a', job: 'a1', attempt: 1, seq: 1, type: 'started' },
    { id: 'b', job: 'a ', attempt: 1, seq: 1, type: 'started' },
    { id: 'c', job: 'a', attempt: 10, seq: 1, type: 'started' },
    { id: 'd', job: 'a', attempt: 2, seq: 1, type: 'started' },
    { id: 'e', job: 'B', attempt: 1, seq: 1, type: 'started' },
    { id: 'f', job: 'Z', attempt: 1, seq: 1, type: 'started' },
  ]));
  assert.deepEqual(report.jobs.map(job => job.job), ['B', 'Z', 'a', 'a ', 'a1']);
  assert.deepEqual(report.jobs[2].attempts.map(attempt => attempt.attempt), [2, 10]);
});

test('CLI: success, invalid args, unreadable input, invalid events', () => {
  const dir = mkdtempSync(join(tmpdir(), 'receipt-report-'));
  try {
    const good = join(dir, 'good.jsonl');
    writeFileSync(good, jsonl([
      { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
      { id: 't', job: 'j', attempt: 1, seq: 2, type: 'succeeded' },
    ]));

    const ok = runCli(good);
    assert.equal(ok.status, 0, ok.stderr);
    assert.deepEqual(JSON.parse(ok.stdout), {
      jobs: [{ job: 'j', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 1, finishedSeq: 2 }] }],
      duplicates: 0,
    });
    assert.ok(ok.stdout.endsWith('\n'));
    assert.equal(ok.stdout, `${JSON.stringify(JSON.parse(ok.stdout))}\n`);
    assert.equal(ok.stderr, '');

    const noArgs = runCli();
    assert.equal(noArgs.status, 2, noArgs.stdout + noArgs.stderr);
    assert.equal(noArgs.stdout, '');
    assert.ok(noArgs.stderr.length > 0);

    const twoArgs = runCli(good, good);
    assert.equal(twoArgs.status, 2);
    assert.equal(twoArgs.stdout, '');
    assert.ok(twoArgs.stderr.length > 0);

    const missing = runCli(join(dir, 'does-not-exist.jsonl'));
    assert.equal(missing.status, 2);
    assert.equal(missing.stdout, '');
    assert.ok(missing.stderr.length > 0);

    const bad = join(dir, 'bad.jsonl');
    writeFileSync(bad, jsonl([
      { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
      { id: 't', job: 'j', attempt: 1, seq: 1, type: 'succeeded' },
    ]));
    const badRun = runCli(bad);
    assert.equal(badRun.status, 2);
    assert.equal(badRun.stdout, '');
    assert.ok(badRun.stderr.length > 0);

    const invalidJson = join(dir, 'invalid.jsonl');
    writeFileSync(invalidJson, '{oops\n');
    const invalidRun = runCli(invalidJson);
    assert.equal(invalidRun.status, 2);
    assert.equal(invalidRun.stdout, '');
    assert.ok(invalidRun.stderr.length > 0);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('importing the module does not run the CLI', () => {
  assert.equal(typeof reduceEvents, 'function');
});

