    const first = uniqueEvents.get(event.id);
    if (first === undefined) {
      uniqueEvents.set(event.id, event);
    } else if (sameRequiredFields(first, event)) {
      duplicates += 1;
    } else {
      fail(`line ${lineNo}: duplicate id with different required fields: ${JSON.stringify(event.id)}`);
    }
  }

