      // identical ids were deduplicated) or a contradiction (both succeeded
      // and failed present). Both are errors.
      if (record.terminal !== null) {
        fail(`job ${JSON.stringify(event.job)} attempt ${event.attempt}: repeated or contradictory terminal event`);
      }
      record.terminal = event;
    }
  }

  const jobs = [];
