+    { id: 't1', job: 'j', attempt: 1, seq: 2, type: 'succeeded' },
+    { id: 't2', job: 'j', attempt: 1, seq: 3, type: 'succeeded' },
+  ])));
+  assert.throws(() => reduceEvents(jsonl([
+    { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
+    { id: 't1', job: 'j', attempt: 1, seq: 2, type: 'succeeded' },
+    { id: 't2', job: 'j', attempt: 1, seq: 3, type: 'failed' },
+  ])));
+});
+
+test('terminal seq must be strictly greater than start seq', () => {
+  const start = { id: 's', job: 'j', attempt: 1, seq: 5, type: 'started' };
+  assert.throws(() => reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 5, type: 'succeeded' }])));
+  assert.throws(() => reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 4, type: 'failed' }])));
+  // strictly greater passes
+  assert.equal(reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 6, type: 'succeeded' }])).jobs[0].attempts[0].status, 'succeeded');
+});
+
+test('attempt gaps are allowed and attempts are independent', () => {
+  const report = reduceEvents(jsonl([
+    { id: 's1', job: 'j', attempt: 1, seq: 1, type: 'started' },
+    { id: 's5', job: 'j', attempt: 5, seq: 1, type: 'started' },
+    { id: 't5', job: 'j', attempt: 5, seq: 2, type: 'failed' },
+    { id: 's9', job: 'j', attempt: 9, seq: 2, type: 'started' },
+  ]));
+  assert.deepEqual(report.jobs, [{ job: 'j', attempts: [
+    { attempt: 1, status: 'running', startedSeq: 1, finishedSeq: null },
+    { attempt: 5, status: 'failed', startedSeq: 1, finishedSeq: 2 },
+    { attempt: 9, status: 'running', startedSeq: 2, finishedSeq: null },
+  ]}]);
+});
+
+test('seqs may be shared across attempts and jobs', () => {
+  const report = reduceEvents(jsonl([
+    { id: 's1', job: 'j', attempt: 1, seq: 5, type: 'started' },
+    { id: 't1', job: 'j', attempt: 1, seq: 9, type: 'failed' },
+    { id: 's2', job: 'j', attempt: 2, seq: 5, type: 'started' },
+    { id: 'sk', job: 'k', attempt: 1, seq: 4, type: 'started' },
+    { id: 'tk', job: 'k', attempt: 1, seq: 5, type: 'succeeded' },
+  ]));
+  assert.deepEqual(report, {
+    jobs: [
+      { job: 'j', attempts: [
+        { attempt: 1, status: 'failed', startedSeq: 5, finishedSeq: 9 },
+        { attempt: 2, status: 'running', startedSeq: 5, finishedSeq: null },
+      ]},
+      { job: 'k', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 4, finishedSeq: 5 }]},
+    ],
+    duplicates: 0,
+  });
+});
+
+test('field validation is strict and never coerces', () => {
+  const ok = { id: 'a', job: 'j', attempt: 1, seq: 0, type: 'started' };
+  const bad = [
+    { ...ok, attempt: 0 },
+    { ...ok, attempt: -1 },
+    { ...ok, attempt: 1.5 },
+    { ...ok, attempt: '1' },
+    { ...ok, attempt: 2 ** 53 },
+    { ...ok, attempt: true },
+    { ...ok, seq: -1 },
+    { ...ok, seq: 0.5 },
+    { ...ok, seq: '0' },
+    { ...ok, seq: 2 ** 53 },
+    { ...ok, id: '' },
+    { ...ok, id: 1 },
+    { ...ok, job: '' },
+    { ...ok, job: null },
+    { ...ok, type: 'Started' },
+    { ...ok, type: 'done' },
+    { ...ok, type: 5 },
+  ];
+  for (const event of bad) {
+    assert.throws(() => reduceEvents(jsonl([event])), undefined, JSON.stringify(event));
+  }
+  assert.throws(() => reduceEvents(jsonl([{ job: 'j', attempt: 1, seq: 0, type: 'started' }])), undefined, 'missing id');
+  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'j', seq: 0, type: 'started' }])), undefined, 'missing attempt');
+  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'j', attempt: 1, type: 'started' }])), undefined, 'missing seq');
+  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'j', attempt: 1, seq: 0 }])), undefined, 'missing type');
+  // safe-integer boundary is valid
+  assert.equal(reduceEvents(jsonl([{ ...ok, seq: 2 ** 53 - 1 }])).duplicates, 0);
+});
+
+test('non-object or invalid JSON lines are rejected', () => {
+  for (const line of ['null', '[1]', '42', '"x"', 'true', '{bad']) {
+    assert.throws(() => reduceEvents(line), undefined, line);
+  }
+});
+
+test('ids such as __proto__ and whitespace/unicode strings are ordinary', () => {
+  const report = reduceEvents(jsonl([
+    { id: '__proto__', job: 'j', attempt: 1, seq: 1, type: 'started' },
+    { id: 's2', job: 'job with spaces', attempt: 1, seq: 1, type: 'started' },
+    { id: '  spaced id  ', job: 'job with spaces', attempt: 1, seq: 2, type: 'succeeded' },
+    { id: 'unicodé', job: '日本 job', attempt: 1, seq: 0, type: 'started' },
+  ]));
+  assert.deepEqual(report.jobs.map(job => job.job), ['j', 'job with spaces', '日本 job']);
+  assert.equal(report.jobs[0].attempts[0].status, 'running');
+  assert.equal(report.jobs[1].attempts[0].status, 'succeeded');
+  // __proto__ did not escape into the result object or Object.prototype
+  assert.equal(Object.hasOwn(report, '__proto__'), false);
+  assert.equal(Object.hasOwn({}, 'polluted'), false);
+});
+
+test('jobs sort by UTF-16 code units, attempts numerically', () => {
+  const report = reduceEvents(jsonl([
+    { id: 'a', job: 'a1', attempt: 1, seq: 1, type: 'started' },
+    { id: 'b', job: 'a ', attempt: 1, seq: 1, type: 'started' },
+    { id: 'c', job: 'a', attempt: 10, seq: 1, type: 'started' },
+    { id: 'd', job: 'a', attempt: 2, seq: 1, type: 'started' },
+    { id: 'e', job: 'B', attempt: 1, seq: 1, type: 'started' },
+    { id: 'f', job: 'Z', attempt: 1, seq: 1, type: 'started' },
+  ]));
+  assert.deepEqual(report.jobs.map(job => job.job), ['B', 'Z', 'a', 'a ', 'a1']);
+  assert.deepEqual(report.jobs[2].attempts.map(attempt => attempt.attempt), [2, 10]);
+});
+
+test('CLI: success, invalid args, unreadable input, invalid events', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'receipt-report-'));
+  try {
+    const good = join(dir, 'good.jsonl');
+    writeFileSync(good, jsonl([
+      { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
+      { id: 't', job: 'j', attempt: 1, seq: 2, type: 'succeeded' },
+    ]));
+
+    const ok = runCli(good);
+    assert.equal(ok.status, 0, ok.stderr);
+    assert.deepEqual(JSON.parse(ok.stdout), {
+      jobs: [{ job: 'j', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 1, finishedSeq: 2 }] }],
+      duplicates: 0,
+    });
+    assert.ok(ok.stdout.endsWith('\n'));
+    assert.equal(ok.stdout, `${JSON.stringify(JSON.parse(ok.stdout))}\n`);
+    assert.equal(ok.stderr, '');
+
+    const noArgs = runCli();
+    assert.equal(noArgs.status, 2, noArgs.stdout + noArgs.stderr);
+    assert.equal(noArgs.stdout, '');
+    assert.ok(noArgs.stderr.length > 0);
+
+    const twoArgs = runCli(good, good);
+    assert.equal(twoArgs.status, 2);
+    assert.equal(twoArgs.stdout, '');
+    assert.ok(twoArgs.stderr.length > 0);
+
+    const missing = runCli(join(dir, 'does-not-exist.jsonl'));
+    assert.equal(missing.status, 2);
+    assert.equal(missing.stdout, '');
+    assert.ok(missing.stderr.length > 0);
+
+    const bad = join(dir, 'bad.jsonl');
+    writeFileSync(bad, jsonl([
+      { id: 's', job: 'j', attempt: 1, seq: 1, type: 'started' },
+      { id: 't', job: 'j', attempt: 1, seq: 1, type: 'succeeded' },
+    ]));
+    const badRun = runCli(bad);
+    assert.equal(badRun.status, 2);
+    assert.equal(badRun.stdout, '');
+    assert.ok(badRun.stderr.length > 0);
+
+    const invalidJson = join(dir, 'invalid.jsonl');
+    writeFileSync(invalidJson, '{oops\n');
+    const invalidRun = runCli(invalidJson);
+    assert.equal(invalidRun.status, 2);
+    assert.equal(invalidRun.stdout, '');
+    assert.ok(invalidRun.stderr.length > 0);
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
+
+test('importing the module does not run the CLI', () => {
+  assert.equal(typeof reduceEvents, 'function');
+});

